        public static string T(string key)
        {
            if (!Table.TryGetValue(key, out string[] v)) return key;
            int i = Language == "uz" ? 1 : Language == "ru" ? 2 : 0;
            return string.IsNullOrEmpty(v[i]) ? v[0] : v[i];
        }
